from fnmatch import fnmatch, fnmatchcase, translate, filter, filterfalse

def _t():
    try:
        fnmatch(*('test', b'*'))
    except TypeError:
        pass
    try:
        fnmatch(*(b'test', '*'))
    except TypeError:
        pass
    try:
        fnmatchcase(*('test', b'*'))
    except TypeError:
        pass
    try:
        fnmatchcase(*(b'test', '*'))
    except TypeError:
        pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

def _t():
    from fnmatch import _translate
    blocks = ['a^b', '***', '?', '?', '[a-z]', '[1-9]', '*', '++', '[[a']
    parts, star_indices = _translate(''.join(blocks), '*', '.')
    expect_parts = ['a', '\\^', 'b', '*', '.', '.', '[a-z]', '[1-9]', '*', '\\+', '\\+', '\\[', '\\[', 'a']
    assert parts == expect_parts, ('assertListEqual', parts, expect_parts)
    assert star_indices == [3, 8], ('assertListEqual', star_indices, [3, 8])
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

